<script setup lang="ts">
import { computed, ref, watch, type DeepReadonly } from 'vue'
import InfoSheet from './InfoSheet.vue'
import CapabilityGap from './CapabilityGap.vue'
import {directionRanking} from '../lib/action-insights.mjs'
import DetailPopover from './DetailPopover.vue'
import UiIcon from './UiIcon.vue'
const comparisonOpen=ref(false),prioritiesOpen=ref(false),order=ref('original')
const preferences=ref([{label:'专业对口',value:3},{label:'岗位数量',value:3},{label:'起薪水平',value:3},{label:'稳定性',value:3},{label:'通勤与地点',value:3}])
import type { DirectionPlanListView, DirectionPlanView } from '../api/backend-types'
const props = defineProps<{ plans: DeepReadonly<DirectionPlanListView>; saving: boolean; error: string }>()
defineEmits<{ select: [id: string] }>()
const ranked=computed(()=>directionRanking(props.plans.plans??[],order.value))
const validScore=(score:unknown):score is number=>typeof score==='number'&&Number.isFinite(score)&&score>=0&&score<=1
const preferenceQuestion=computed(()=>'比较这些方向时，我希望考虑以下偏好（1最低，5最高）：'+preferences.value.map(p=>p.label+' '+p.value).join('、')+'。请结合已有资料讨论取舍，缺少证据的分项不要编造评分。')
const candidate = ref('')
const selected = computed(() => props.plans.selected_id || props.plans.plans?.find(p => p.selected)?.id || '')
watch(selected, id => { candidate.value = id }, { immediate: true })
const invalidSelected = computed(() => !!selected.value&&!props.plans.plans?.some(p=>p.id===selected.value))
const selectedName = computed(() => props.plans.plans?.find(p=>p.id===selected.value)?.name || '此前保存的方向')
const pending = computed(() => props.plans.plans?.find(p => p.id === candidate.value))
const roles = { main: '主攻', parallel: '平行', fallback: '保底' }
const preview=(text:string)=>text.length>110 ? text.slice(0,110)+'…' : text
const criteria = ['方向目标','匹配依据','方向要求','当前情况','补齐建议','主要风险']
function values(plan: DeepReadonly<DirectionPlanView>, criterion: string): readonly string[] {
  if (criterion==='方向目标') return [plan.target_desc || '尚未提供目标说明']
  if (criterion==='匹配依据') return [plan.fit_reason || '尚未提供匹配依据']
  if (criterion==='主要风险') return [plan.main_risk || '尚未提供具体风险，请进一步核对']
  const list = plan.gaps?.map(g => criterion==='方向要求' ? g.requirement : criterion==='当前情况' ? g.current_state || '尚待补充' : g.suggestion || '尚未提供建议') ?? []
  return list.length ? list : ['本次未提供差距明细']
}
</script>
<template><section class="direction-details"><p v-if="error" class="ws-field-error" role="alert">{{ error }}</p><p class="direction-current">{{ selected ? '当前方向：'+selectedName : '尚未确认方向。先逐项比较，再作选择。' }}</p><p v-if="invalidSelected" class="asset-notice" role="status">此前选择暂未出现在这次方案中。请重新读取，或比较后选择新的方向；原选择记录仍保留。</p><p v-if="plans.match_score_method" class="ws-muted">匹配判断依据：{{ plans.match_score_method }}</p>
<template v-if="plans.plans?.length"><div class="ws-inline-actions restored-direction-tools"><label class="ws-field">排列方式<select v-model="order"><option value="original">方案原顺序</option><option value="score">按后端匹配分排序</option></select></label><button class="btn" @click="prioritiesOpen=true">调整选择偏好</button><CapabilityGap title="机会与门槛象限" reason="尚未提供机会和门槛两个坐标值，不能把方向序号当成位置。"/></div><div class="live-direction-list"><article v-for="plan in ranked" :key="plan.id" class="live-direction-row"><div><span class="ws-muted">{{ roles[plan.role] }}{{ selected===plan.id ? ' · 当前方向' : '' }}</span><h2>{{ plan.name }}</h2><div class="restored-score"><template v-if="validScore(plan.match_score)"><strong>{{Math.round(plan.match_score*100)}}<small> / 100 匹配分</small></strong><meter min="0" max="1" :value="plan.match_score" :aria-label="plan.name+'匹配分'"/></template><span v-else class="ws-muted">匹配分未提供</span></div><p>{{ preview(plan.target_desc || '尚未提供目标说明') }}</p><p class="ws-attention">{{ preview(plan.main_risk || '具体风险有待核对') }}</p><DetailPopover :title="plan.name+' · 匹配依据'" :label="'查看'+plan.name+'匹配依据'"><template #trigger>匹配依据<UiIcon name="info" :size="16"/></template><p>{{ plan.fit_reason || '尚未提供匹配依据' }}</p></DetailPopover></div><label class="direction-radio"><input v-model="candidate" type="radio" name="direction-candidate" :value="plan.id" :disabled="saving"/>{{ selected===plan.id?'当前方向':'作为候选' }}</label></article></div><button class="btn" @click="comparisonOpen=true">逐项核对目标、差距与建议<UiIcon name="arrow" :size="16"/></button><InfoSheet :open="comparisonOpen" shape="panel" title="方向目标、差距与建议" @close="comparisonOpen=false"><div class="compare-desktop local-table-scroll"><table class="fact-table"><caption class="sr-only">最新方向的目标、要求、现状、建议与风险</caption><thead><tr><th scope="col">比较项目</th><th v-for="p in plans.plans" :key="p.id" scope="col"><small>{{ roles[p.role] }}</small>{{ p.name }}</th></tr></thead><tbody><tr v-for="criterion in criteria" :key="criterion"><th scope="row">{{ criterion }}</th><td v-for="p in plans.plans" :key="p.id"><ol :class="{'ws-attention':criterion==='主要风险'}"><li v-for="(v,i) in values(p,criterion)" :key="i">{{ v }}</li></ol></td></tr><tr><th scope="row">候选方向</th><td v-for="p in plans.plans" :key="p.id"><label class="direction-radio"><input v-model="candidate" name="live-direction-desktop" type="radio" :value="p.id" :disabled="saving"/>{{ selected===p.id?'当前方向':'作为候选' }}</label></td></tr></tbody></table></div>
<div class="compare-mobile"><section v-for="criterion in criteria" :key="criterion" class="compare-criterion"><h3>{{ criterion }}</h3><article v-for="p in plans.plans" :key="p.id"><strong>{{ roles[p.role] }} · {{ p.name }}</strong><ol :class="{'ws-attention':criterion==='主要风险'}"><li v-for="(v,i) in values(p,criterion)" :key="i">{{ v }}</li></ol></article></section><fieldset class="ws-field"><legend>候选方向</legend><label v-for="p in plans.plans" :key="p.id" class="direction-radio"><input v-model="candidate" name="live-direction-mobile" type="radio" :value="p.id" :disabled="saving"/>{{ p.name }}{{ selected===p.id?' · 当前方向':'' }}</label></fieldset></div>
</InfoSheet><section class="direction-confirm"><div><h2>{{ pending?.name || '比较后再确认' }}</h2><p>{{ candidate===selected&&selected?'当前选择已确认，仍可调整。':'确认会保存你的方向选择，已有执行记录保留。' }}</p></div><button class="btn btn--primary" :disabled="saving||!candidate||candidate===selected" @click="$emit('select',candidate)">{{ saving?'正在保存…':'确认方向' }}</button></section><p v-if="selected" class="desk-status" role="status">已确认「{{ selectedName }}」。报告和计划的更新状态请分别核对。</p><nav class="ws-related"><RouterLink to="/report?focus=versions">核对报告更新状态</RouterLink><RouterLink to="/plan">查看阶段计划</RouterLink></nav></template><p v-else class="ws-empty">当前尚未取得方向方案。可在咨询中补充必要信息。</p><div class="information-print-only"><h2>方向比较明细</h2><section v-for="p in plans.plans" :key="p.id"><h3>{{p.name}} · {{roles[p.role]}}</h3><section v-for="criterion in criteria" :key="criterion"><h4>{{criterion}}</h4><ul><li v-for="(v,i) in values(p,criterion)" :key="i">{{v}}</li></ul></section></section></div><InfoSheet :open="prioritiesOpen" shape="panel" title="调整选择偏好" @close="prioritiesOpen=false"><div class="ws-section-head"><h2>我看重什么</h2><button class="btn" @click="preferences.forEach(p=>p.value=3)">恢复同等权重</button></div><fieldset v-for="p in preferences" :key="p.label" class="restored-preference"><legend>{{p.label}}</legend><label v-for="(label,i) in ['低','较低','适中','较高','高']" :key="label"><input v-model.number="p.value" type="radio" :name="'priority-'+p.label" :value="i+1"/>{{label}}</label></fieldset><p class="ws-muted">这些偏好是当前页面的讨论草稿，不会改写已保存的方向。</p><CapabilityGap title="按偏好重新计算排序" reason="已有总体匹配分，但缺少五项分项评分及偏好保存、重新评分接口。调整偏好不会假装改变匹配分。"/><div class="ws-inline-actions ws-section"><button class="btn" disabled>按权重重新排序（待支持）</button><RouterLink class="btn btn--primary" :to="'/chat?question='+encodeURIComponent(preferenceQuestion)">带着偏好咨询</RouterLink></div></InfoSheet></section></template>
<style scoped>.restored-direction-tools{gap:16px;align-items:center;margin:20px 0}.restored-score{display:flex;gap:16px;align-items:center;margin:12px 0}.restored-score strong{font-size:24px;color:var(--c-primary)}.restored-score small{font-size:12px;color:var(--c-text-3);font-weight:400}.restored-score meter{width:100px;height:8px;accent-color:var(--c-primary)}.restored-preference{display:flex;flex-wrap:wrap;gap:12px;padding:16px 0;border:0;border-bottom:1px solid var(--c-border)}.restored-preference legend{padding-top:14px;font-weight:600}.restored-preference label{display:flex;align-items:center;gap:6px;min-height:40px}</style>
